function focusDescriptor(){const e=document.activeElement;if(!e||e===document.body)return null;if(e.id)return '#'+CSS.escape(e.id);for(const key of ['data-detail','data-pick','data-map','data-tab','data-layout','data-room','data-day','data-group','data-action','data-now-mode'])if(e.hasAttribute(key))return '['+key+'="'+CSS.escape(e.getAttribute(key))+'"]';return null;}
function restoreFocus(selector){const e=selector&&document.querySelector(selector);if(e&&!e.closest('[hidden]'))e.focus({preventScroll:true});}
function hideDialog(){dialogContext=null;if($('#detail').open)$('#detail').close();}
function readUI(){return {tab,day,query,room,level,aux,layout,searchScope,browsedRoom,searchOpen,exploring,exploreDate,exploreTime,nowMode,opened:[...opened],scroll:window.scrollY,scrolls:{...scrolls},dialog:$('#detail').open?structuredClone(dialogContext):null,focus:focusDescriptor(),returnFocus,grid:$('.schedule-scroll')?{left:$('.schedule-scroll').scrollLeft,top:$('.schedule-scroll').scrollTop}:null};}
function applyUI(u){const oldReturn=returnFocus;({tab,day,query,room,level,aux,layout,searchScope,browsedRoom,searchOpen,exploring,exploreDate,exploreTime,nowMode}=u);returnFocus=u.returnFocus;Object.assign(scrolls,u.scrolls);opened.clear();(u.opened??[]).forEach(id=>opened.add(id));if(innerWidth<768&&layout==='grid')layout='time';hideDialog();render();if(u.dialog){dialogContext=u.dialog;renderDialog();$('#detail').showModal();}requestAnimationFrame(()=>{window.scrollTo(0,u.scroll??0);const grid=$('.schedule-scroll');if(grid&&u.grid){grid.scrollLeft=u.grid.left;grid.scrollTop=u.grid.top;}restoreFocus(u.focus||oldReturn);});}
function setTab(next){if(!['now','program','route'].includes(next)||next===tab)return;hideDialog();scrolls[tab]=window.scrollY;if(next==='program'&&layout!=='room'){layout='room';scrolls.program=0;}tab=next;searchOpen=false;render();window.scrollTo({top:scrolls[tab]??0,behavior:'instant'});}
function openDialog(context){if(!$('#detail').open)returnFocus=focusDescriptor();dialogContext=context;renderDialog();if(!$('#detail').open)$('#detail').showModal();$('#closeDetail').focus({preventScroll:true});}

