document.addEventListener('click',e=>{
 const el=e.target.closest('button');if(!el||!data)return;
 if(el.dataset.collection){openDialog({kind:'collection',ids:el.dataset.collection.split(',')});return;}
 if(el.dataset.nowMode){const mode=el.dataset.nowMode;if(mode==='custom'){openDialog({kind:'time-selector',date:exploreDate});return;}nowMode=mode;exploring=mode==='next';if(exploring){const next=nextBlock(eventClock())[0];if(!next){exploring=false;nowMode='now';showToast('No quedan bloques posteriores.');}else{exploreDate=next.date;exploreTime=next.start;}}render();return;}
 if(el.dataset.speaker){openDialog({kind:'speaker',id:el.dataset.speaker,name:el.dataset.speakerName});return;}
 if(el.dataset.upcoming){day=el.dataset.upcoming;room='';query='';level='';setTab('program');return;}
 if(el.dataset.tab){setTab(el.dataset.tab);return;}
 if(el.dataset.day){day=el.dataset.day;opened.clear();render();return;}
 if(el.dataset.layout){layout=el.dataset.layout;render();return;}
 if(el.dataset.room){browsedRoom=el.dataset.room;render();return;}
 if(el.dataset.level){level=level===el.dataset.level?'':el.dataset.level;render();return;}
 if(el.dataset.gap){const [start,end]=el.dataset.gap.split(',').map(Number);openDialog({kind:'gap',date:day,start,end});return;}
 if(el.dataset.keep){mutate(r=>keepActivity(data.activities,r,el.dataset.keep),'Elección conservada; se excluyeron solo sus coincidencias.');return;}
 if(el.dataset.map){openDialog({kind:'map',roomId:el.dataset.map});return;}
 if(el.dataset.pick){const a=lookup.activities[el.dataset.pick];if(a)mutate(r=>setRule(r,'activities',a.id,!selected(a,r)),selected(a,state.rules)?'Actividad excluida de tu ruta.':'Actividad agregada a tu ruta.');return;}
 if(el.dataset.inherit){mutate(r=>setRule(r,'activities',el.dataset.inherit,undefined),'La actividad vuelve a seguir su grupo.');return;}
 if(el.dataset.detail){openDialog({kind:'detail',id:el.dataset.detail});return;}
 if(el.dataset.group){openDialog({kind:'group',scope:el.dataset.group,key:el.dataset.key,date:day,allDays:false});return;}
 if(el.dataset.groupRule){const ctx=dialogContext;if(ctx?.kind!=='group')return;const mode=el.dataset.groupRule,items=groupActivities(ctx);mutate(r=>{let next=structuredClone(r);if(mode==='reset'){items.forEach(a=>{delete next.activities[a.id];if(ctx.scope==='room')delete next.blocks[a.blockId]});}else{const val=mode==='include'?true:mode==='exclude'?false:undefined,keys=ctx.scope==='block'?[ctx.key]:[...new Set(items.map(roomKey))];keys.forEach(k=>next=setRule(next,ctx.scope==='block'?'blocks':'rooms',k,val));}return next;},mode==='reset'?'Excepciones restablecidas.':'Regla actualizada; se conservaron las excepciones.');return;}
 const action=el.dataset.action;
 if(action==='apply-block'){exploreDate=$('#blockDate').value;exploreTime=$('#blockTime').value;if(!exploreTime)return;exploring=true;nowMode='custom';hideDialog();render();}

 if(action==='undo'&&undo){const prior=undo;undo=null;state.rules=prior;save();render();if(dialogContext)renderDialog();showToast('Cambio deshecho.');}
 if(action==='clear-filters'){query='';room='';level='';aux=true;searchScope='day';render();}
 if(action==='explore'){exploring=!exploring;if(exploring){const real=eventClock();exploreDate=visibleDates().includes(real.date)?real.date:day;exploreTime=visibleDates().includes(real.date)?real.time:'09:00';}room='';render();}
 if(action==='go-room'){day=clock().date;browsedRoom=el.dataset.key;layout='room';setTab('program');}
 if(action==='toggle-map'&&dialogContext?.kind==='detail'){dialogContext.map=!dialogContext.map;renderDialog();}
 if(action==='conflicts')openDialog({kind:'conflicts'});
 if(action==='conflict-filter'){conflictOnly=!conflictOnly;render();}
 if(action==='clear-dialog')openDialog({kind:'clear'});
 if(action==='clear-route'){mutate(()=>emptyRules(),'Ruta restablecida.');hideDialog();}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;render(true);navigation?.replace();}});
document.addEventListener('change',e=>{const id=e.target.id;if(id==='blockDate'){dialogContext.date=e.target.value;renderDialog();return;}if(id==='searchScope')searchScope=e.target.value;if(id==='roomFilter')room=e.target.value;if(id==='levelFilter')level=e.target.value;if(id==='auxToggle')aux=e.target.checked;if(id==='exploreDate'){exploreDate=e.target.value;day=exploreDate;room='';}if(id==='exploreTime'){if(!e.target.value)return;exploreTime=e.target.value;}if(id==='allDays'&&dialogContext?.kind==='group'){dialogContext.allDays=e.target.checked;renderDialog();return;}if(['searchScope','roomFilter','levelFilter','auxToggle','exploreDate','exploreTime'].includes(id)){render();navigation?.replace();}});
$('#searchButton').addEventListener('click',()=>{if(tab!=='program')setTab('program');searchOpen=!searchOpen;render();if(searchOpen){$('#headerSearch details').open=true;$('#search').focus();}});
$('#closeDetail').addEventListener('click',()=>navigation.close());$('#detail').addEventListener('cancel',e=>{e.preventDefault();navigation.close();});$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const b=e.target.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)navigation.close();}});$('#mapButton').addEventListener('click',()=>data&&openDialog({kind:'venue-map'}));$('#infoButton').addEventListener('click',()=>data&&openDialog({kind:'info'}));
